var messagingApi = {
	conversations: async () => {
		return unwrap((await apiClient.get(API_ENDPOINTS.messaging.conversations)).data);
	},
	messages: async (conversationId, params = {}) => {
		return unwrapPage((await apiClient.get(API_ENDPOINTS.messaging.messages(conversationId), { params })).data);
	},
	send: async (conversationId, body) => {
		return unwrap((await apiClient.post(API_ENDPOINTS.messaging.messages(conversationId), { body })).data);
	},
	startConversation: async (input) => {
		return unwrap((await apiClient.post(API_ENDPOINTS.messaging.conversations, input)).data);
	},
	directory: async () => {
		return unwrap((await apiClient.get(API_ENDPOINTS.messaging.directory)).data);
	},
	unread: async () => {
		return unwrap((await apiClient.get(API_ENDPOINTS.messaging.unread)).data);
	},
	notifications: async (params = {}) => {
		const envelope = (await apiClient.get(API_ENDPOINTS.messaging.notifications, { params })).data;
		return {
			...unwrapPage(envelope),
			unreadCount: Number(envelope.meta?.unreadCount ?? 0)
		};
	},
	markRead: async (notificationId) => {
		await apiClient.post(API_ENDPOINTS.messaging.readNotification(notificationId), {});
	},
	markAllRead: async () => {
		await apiClient.post(API_ENDPOINTS.messaging.readAllNotifications, {});
	}
};
