var filesApi = {
	upload: async (file, input) => {
		const form = new FormData();
		form.append("file", file);
		form.append("ownerType", input.ownerType);
		if (input.ownerId) form.append("ownerId", input.ownerId);
		if (input.patientId) form.append("patientId", input.patientId);
		return unwrap((await apiClient.post(API_ENDPOINTS.files.upload, form)).data);
	},
	uploadAvatar: async (file) => {
		const form = new FormData();
		form.append("file", file);
		return unwrap((await apiClient.post(API_ENDPOINTS.profile.avatar, form)).data);
	},
	myAvatar: async () => {
		return unwrap((await apiClient.get(API_ENDPOINTS.profile.avatar)).data);
	},
	patientDocuments: async (patientId, params = {}) => {
		return unwrapPage((await apiClient.get(API_ENDPOINTS.patients.documents(patientId), { params })).data);
	},
	myDocuments: async (params = {}) => {
		return unwrapPage((await apiClient.get(API_ENDPOINTS.files.myDocuments, { params })).data);
	},
	download: async (fileId, fileName = "document") => {
		await downloadFile(API_ENDPOINTS.files.download(fileId), fileName);
	},
	remove: async (fileId) => {
		await apiClient.delete(API_ENDPOINTS.files.byId(fileId));
	}
};
