var diagnosticsApi = {
	radiologyOrders: async (params = {}) => {
		return unwrapPage((await apiClient.get(API_ENDPOINTS.diagnostics.radiologyOrders, { params })).data);
	},
	updateRadiologyStatus: async (orderId, status) => {
		await apiClient.patch(API_ENDPOINTS.diagnostics.radiologyStatus(orderId), { status });
	},
	submitRadiologyReport: async (orderId, input) => {
		await apiClient.post(API_ENDPOINTS.diagnostics.radiologyReport(orderId), input);
	},
	equipment: async () => {
		return unwrap((await apiClient.get(API_ENDPOINTS.diagnostics.equipment)).data);
	},
	maintenanceLog: async (equipmentId) => {
		return unwrap((await apiClient.get(API_ENDPOINTS.diagnostics.maintenance, { params: { equipmentId } })).data);
	},
	logMaintenance: async (equipmentId, input) => {
		await apiClient.post(API_ENDPOINTS.diagnostics.equipmentMaintenance(equipmentId), input);
	},
	setEquipmentStatus: async (equipmentId, input) => {
		await apiClient.patch(API_ENDPOINTS.diagnostics.equipmentStatus(equipmentId), input);
	}
};
